// Screen 04 of 29. Generated by Google Stitch, source folder 4-map_results.
// Rebuilt 3 August 2026.
//
// WHAT WAS WRONG WITH THE GENERATED VERSION
// The map was `Container(color: Colors.grey.shade200)` with a grey icon, and
// the four price pins were `Positioned` widgets at fixed pixel offsets. Those
// pins would sit still while the map panned underneath them, so a listing
// would appear to be somewhere it is not. That is worse than no map.
//
// Real markers move with the map because they belong to it.
//
// MEMORY. This app has previously been killed by iOS Jetsam, and a map is one
// of the three heaviest things a Flutter app can do. Two rules:
//   * ONE GoogleMap alive at a time across the whole Short Stay feature
//   * the controller is disposed, following widgets/live_tracking_map.dart
import 'package:flutter/material.dart';
import 'package:google_fonts/google_fonts.dart';
import 'package:google_maps_flutter/google_maps_flutter.dart';
import '../models/stay_listing.dart';
import '../theme/stay_colors.dart';

class MapResultsScreen extends StatefulWidget {
  const MapResultsScreen({
    super.key,
    this.listings = const [],
    this.onOpenListing,
    this.onShowList,
  });

  /// The same result set the list view is showing. Passed in rather than
  /// fetched here, so the two views cannot disagree about what was found.
  final List<StayListing> listings;

  final void Function(String listingId)? onOpenListing;
  final VoidCallback? onShowList;

  @override
  State<MapResultsScreen> createState() => _MapResultsScreenState();
}

class _MapResultsScreenState extends State<MapResultsScreen> {
  // Charing Cross. The conventional point from which distances to London are
  // measured, and a sane fallback when no listing has coordinates yet.
  static const LatLng _fallbackCentre = LatLng(51.50735, -0.12776);

  GoogleMapController? _map;
  final PageController _cards = PageController(viewportFraction: 0.86);
  int _selected = 0;

  @override
  void dispose() {
    // Both, always. A leaked map controller holds native resources.
    _map?.dispose();
    _cards.dispose();
    super.dispose();
  }

  List<StayListing> get _plottable =>
      widget.listings.where((l) => l.lat != null && l.lng != null).toList();

  LatLng get _initialCentre {
    final p = _plottable;
    if (p.isEmpty) return _fallbackCentre;
    return LatLng(p.first.lat!, p.first.lng!);
  }

  Set<Marker> get _markers => {
        for (var i = 0; i < _plottable.length; i++)
          Marker(
            markerId: MarkerId(_plottable[i].id),
            position: LatLng(_plottable[i].lat!, _plottable[i].lng!),
            // TODO custom price bubble. Drawing "£112" into a BitmapDescriptor
            // needs a canvas render per listing. Worth doing, not worth
            // blocking on. Hue distinguishes the selected pin meanwhile.
            icon: BitmapDescriptor.defaultMarkerWithHue(
              i == _selected
                  ? BitmapDescriptor.hueAzure
                  : BitmapDescriptor.hueBlue,
            ),
            onTap: () => _selectListing(i),
          ),
      };

  Future<void> _selectListing(int index) async {
    if (index < 0 || index >= _plottable.length) return;
    setState(() => _selected = index);
    if (_cards.hasClients) {
      await _cards.animateToPage(
        index,
        duration: const Duration(milliseconds: 250),
        curve: Curves.easeOut,
      );
    }
    // The animateToPage above is awaited, so the widget may have been
    // disposed by the time we get here. Touching a disposed map controller
    // throws, and it is the classic crash-on-back-button.
    if (!mounted) return;
    final l = _plottable[index];
    await _map?.animateCamera(
      CameraUpdate.newLatLng(LatLng(l.lat!, l.lng!)),
    );
  }

  @override
  Widget build(BuildContext context) {
    final plottable = _plottable;

    return Scaffold(
      backgroundColor: GoOutsColors.pageBackground,
      body: Stack(
        children: [
          if (plottable.isEmpty)
            _noPlottableListings()
          else
            GoogleMap(
              initialCameraPosition:
                  CameraPosition(target: _initialCentre, zoom: 13),
              markers: _markers,
              myLocationEnabled: false,
              myLocationButtonEnabled: false,
              zoomControlsEnabled: false,
              mapToolbarEnabled: false,
              compassEnabled: false,
              onMapCreated: (c) => _map = c,
            ),

          // Back control, above the map.
          SafeArea(
            child: Padding(
              padding: const EdgeInsets.all(12),
              child: _circleButton(
                Icons.arrow_back,
                () => Navigator.of(context).maybePop(),
              ),
            ),
          ),

          if (plottable.isNotEmpty) _carousel(plottable),
          _listToggle(),
        ],
      ),
    );
  }

  Widget _noPlottableListings() => Container(
        color: GoOutsColors.dividerGray,
        child: Center(
          child: Padding(
            padding: const EdgeInsets.all(32),
            child: Column(
              mainAxisAlignment: MainAxisAlignment.center,
              children: [
                const Icon(Icons.map_outlined,
                    size: 48, color: GoOutsColors.outlineVariant),
                const SizedBox(height: 16),
                Text(
                  'Nothing to show on the map',
                  style: GoogleFonts.inter(
                    fontSize: 16,
                    fontWeight: FontWeight.w600,
                    color: GoOutsColors.deepNavy,
                  ),
                ),
                const SizedBox(height: 8),
                Text(
                  'Try widening your search, or switch back to the list.',
                  textAlign: TextAlign.center,
                  style: GoogleFonts.inter(
                    fontSize: 13.5,
                    height: 1.5,
                    color: GoOutsColors.bodyText,
                  ),
                ),
              ],
            ),
          ),
        ),
      );

  Widget _carousel(List<StayListing> listings) => Positioned(
        bottom: 90,
        left: 0,
        right: 0,
        height: 128,
        child: PageView.builder(
          controller: _cards,
          itemCount: listings.length,
          onPageChanged: (i) {
            setState(() => _selected = i);
            final l = listings[i];
            _map?.animateCamera(
              CameraUpdate.newLatLng(LatLng(l.lat!, l.lng!)),
            );
          },
          itemBuilder: (context, i) => Padding(
            padding: const EdgeInsets.symmetric(horizontal: 6),
            child: _card(listings[i]),
          ),
        ),
      );

  Widget _card(StayListing l) {
    final partners = l.locationContext?.partnerCounts;
    return InkWell(
      onTap: widget.onOpenListing == null
          ? null
          : () => widget.onOpenListing!(l.id),
      borderRadius: BorderRadius.circular(12),
      child: Container(
        decoration: BoxDecoration(
          color: GoOutsColors.cardSurface,
          borderRadius: BorderRadius.circular(12),
          boxShadow: [
            BoxShadow(
              color: Colors.black.withValues(alpha: 0.1),
              blurRadius: 8,
              offset: const Offset(0, 4),
            ),
          ],
        ),
        child: Row(
          children: [
            ClipRRect(
              borderRadius:
                  const BorderRadius.horizontal(left: Radius.circular(12)),
              child: SizedBox(
                width: 100,
                height: 128,
                child: l.coverPhotoUrl == null
                    ? Container(
                        color: GoOutsColors.dividerGray,
                        child: const Icon(Icons.home_outlined,
                            color: GoOutsColors.outlineVariant),
                      )
                    : Image.network(
                        l.coverPhotoUrl!,
                        fit: BoxFit.cover,
                        // Decode at display size. A full resolution decode per
                        // card is how a carousel eats memory.
                        cacheWidth: 200,
                        errorBuilder: (_, __, ___) => Container(
                          color: GoOutsColors.dividerGray,
                          child: const Icon(Icons.home_outlined,
                              color: GoOutsColors.outlineVariant),
                        ),
                      ),
              ),
            ),
            Expanded(
              child: Padding(
                padding: const EdgeInsets.all(12),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  mainAxisAlignment: MainAxisAlignment.center,
                  children: [
                    Text(
                      l.title,
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: GoogleFonts.inter(
                        fontSize: 14,
                        fontWeight: FontWeight.bold,
                        color: GoOutsColors.deepNavy,
                      ),
                    ),
                    const SizedBox(height: 2),
                    Text(
                      l.address.publicLabel,
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: GoogleFonts.inter(
                          fontSize: 12, color: GoOutsColors.bodyText),
                    ),
                    if (partners != null && partners.hasAny) ...[
                      const SizedBox(height: 6),
                      Container(
                        padding: const EdgeInsets.symmetric(
                            horizontal: 8, vertical: 3),
                        decoration: BoxDecoration(
                          color: GoOutsColors.paleBlueTint,
                          borderRadius: BorderRadius.circular(20),
                        ),
                        child: Text(
                          '${partners.halfMile} partners nearby',
                          style: GoogleFonts.inter(
                            fontSize: 11,
                            fontWeight: FontWeight.w600,
                            color: GoOutsColors.primaryBlue,
                          ),
                        ),
                      ),
                    ],
                    const SizedBox(height: 6),
                    Text(
                      '${l.nightlyRate.compact} a night',
                      style: GoogleFonts.inter(
                        fontSize: 14,
                        fontWeight: FontWeight.w700,
                        color: GoOutsColors.deepNavy,
                      ),
                    ),
                  ],
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _listToggle() => Positioned(
        bottom: 28,
        left: 0,
        right: 0,
        child: Center(
          child: ElevatedButton.icon(
            onPressed: widget.onShowList ??
                () => Navigator.of(context).maybePop(),
            icon: const Icon(Icons.list, size: 18),
            label: Text('Show list',
                style: GoogleFonts.inter(
                    fontSize: 14, fontWeight: FontWeight.w600)),
            style: ElevatedButton.styleFrom(
              backgroundColor: GoOutsColors.deepNavy,
              foregroundColor: GoOutsColors.cardSurface,
              elevation: 4,
              padding:
                  const EdgeInsets.symmetric(horizontal: 20, vertical: 12),
              shape: RoundedRectangleBorder(
                borderRadius: BorderRadius.circular(24),
              ),
            ),
          ),
        ),
      );

  Widget _circleButton(IconData icon, VoidCallback onTap) => Material(
        color: GoOutsColors.cardSurface,
        shape: const CircleBorder(),
        elevation: 3,
        child: InkWell(
          customBorder: const CircleBorder(),
          onTap: onTap,
          child: Padding(
            padding: const EdgeInsets.all(10),
            child: Icon(icon, color: GoOutsColors.primaryBlue, size: 22),
          ),
        ),
      );
}
